 {
  Directory.CreateDirectory(output);void Require(bool v,string m){if(!v)throw new Exception(m);}void Steps(World w,int n){for(int i=0;i<n;i++)w.Step(d);}void Cmd(World w,WorldCommand c){var r=w.Apply(c,d);Require(r.Accepted,c.Kind+"/"+c.Text+": "+r.Message);}void Until(World w,Func<bool> done,int limit,string label){for(int i=0;i<limit&&!done();i++)w.Step(d);Require(done(),label+" stalled at "+w.Tick+": "+string.Join(" / ",w.Colony.People.Values.Select(p=>p.Activity))+" | "+string.Join(" / ",w.Solar.Projects.Select(p=>p.Status))+" | jobs="+string.Join(",",w.Autonomy.Jobs.Select(j=>j.Kind+":"+j.DefinitionId+":"+j.Work+":"+j.Path.Count))+" | parts="+w.Resources("f-parts").Total+" glass="+w.Resources("f-glass").Total+" cloth="+w.Resources("f-cloth").Total+" lessons="+string.Join(",",w.Society.Apprentices.Select(a=>a.Lessons)));w.Validate(d);}void Save(string name,World w,string page="Observations"){SaveStore.Write(Path.Combine(output,name+".lastlight"),w,new(){CameraX=64,CameraY=64,OpenTab="World",SolarPage=page,SolarProject=w.Solar.Finale!=""?w.Solar.Finale:w.Solar.Projects.FirstOrDefault(p=>p.Active)?.Id??"Sun"},d);}World Copy(World w)=>JsonSerializer.Deserialize<World>(JsonSerializer.Serialize(w,JsonFormat.Options),JsonFormat.Options)!;
