  desk=w.Entities.First(e=>e.DefinitionId=="study");Cmd(w,new(CommandKind.InstitutionAction,scholar,"Library",TargetId:desk.Id,Text:"found"));var library=w.Society.Institutions.Single();Cmd(w,new(CommandKind.InstitutionAction,apprentice,TargetId:library.Id,Text:"join"));Cmd(w,new(CommandKind.InstitutionAction,scholar,TargetId:apprentice,Quantity:(int)library.Id,Text:"apprentice"));foreach(long id in new[]{scholar,apprentice}){w.Interrupt(id,d);w.Colony.People[id].Schedule=Enumerable.Repeat(ScheduleActivity.Study,24).ToArray();}
