  Require(w.Solar.Refuges.All(r=>r.Level>=1&&r.PartsSpent>0&&r.WoodSpent>0)&&w.Solar.Claims.Count==1,"Regional adaptation/claims not reserve-backed.");Require(w.Solar.Flares>0&&w.Solar.Forecasts.Any(f=>f.Kind=="Flare"&&f.Resolved),"Forecast flare path not exercised.");Save("solar-lastlight",w);var reloaded=SaveStore.Read(Path.Combine(output,"solar-lastlight.lastlight"),d).World;Require(SaveStore.Fingerprint(w)==SaveStore.Fingerprint(reloaded),"Campaign reload differs.");Steps(w,300);Steps(reloaded,300);Require(SaveStore.Fingerprint(w)==SaveStore.Fingerprint(reloaded),"Campaign continuation diverges.");Console.WriteLine("PASS I01/I02 balancing: all five stages traversed without universal destruction; funded adaptations, flares, scarcity claim and deterministic continuation");
  // Returnable ordinary regional expedition; every agreement is signed beside its actual town counter.
  var crew=new[]{scholar,apprentice};foreach(long id in crew){w.Interrupt(id,d);w.Colony.People[id].Drafted=false;}Until(w,()=>w.Resources("meal").Total>=12,15000,"Packed meals");var allies=w.Region.Factions.Where(f=>f.Goodwill>=10).OrderBy(f=>f.Id).Take(3).ToArray();Require(allies.Length==3,"Three feasible starting allies not available.");var town=w.Region.Sites.First(s=>s.Kind=="Town"&&s.FactionId==allies[0].Id);Cmd(w,new(CommandKind.RegionAction,scholar,string.Join(',',crew),TargetId:town.Id,Quantity:6,Text:"depart"));var party=w.Region.Parties.Last();
  void Arrive(RegionSite site){if(party.State=="AtSite")Cmd(w,new(CommandKind.RegionAction,TargetId:party.Id,Quantity:(int)site.Id,Text:"travel"));Until(w,()=>party.State=="AtSite"&&party.SiteId==site.Id,30000,"Regional arrival");if(site.Kind=="Town"){var counter=w.Find(site.MarketId)!;Cmd(w,new(CommandKind.MoveDrafted,scholar,X:counter.X-1,Y:counter.Y,Z:counter.Z));Until(w,()=>Math.Abs(w.Find(scholar)!.X-counter.X)+Math.Abs(w.Find(scholar)!.Y-counter.Y)<=2,10000,"Counter approach");}}
  PatronCompact? patron=null;for(int n=0;n<3;n++){var faction=allies[n];town=w.Region.Sites.First(s=>s.Kind=="Town"&&s.FactionId==faction.Id);Arrive(town);Cmd(w,new(CommandKind.RegionAction,scholar,"Sanctuary",TargetId:party.Id,Text:"treaty"));for(int trade=0;trade<(n==0?4:2);trade++){Cmd(w,new(CommandKind.RegionAction,scholar,"wood",TargetId:party.Id,Text:"buy"));Cmd(w,new(CommandKind.RegionAction,scholar,"wood",TargetId:party.Id,Text:"sell"));}if(n==0){int meals=faction.Reserves["meal"],parts=faction.Reserves["f-parts"];Cmd(w,new(CommandKind.CampaignAction,scholar,"Open access",TargetId:faction.Id,Text:"patron"));patron=w.Solar.Patrons.Last();Require(faction.Reserves["meal"]==meals-6&&faction.Reserves["f-parts"]==parts-6,"Patron aid fabricated.");}}
  var monastery=w.Region.Sites.Single(s=>s.Kind=="Machine monastery");Arrive(monastery);Cmd(w,new(CommandKind.RegionAction,TargetId:party.Id,Text:"return"));Until(w,()=>party.State=="Returned",30000,"Home return");Require(crew.All(id=>!w.IsAway(id)&&!w.Colony.People[id].Drafted),"Expedition crew not returned.");
  foreach(long id in crew)w.Colony.People[id].Schedule=Enumerable.Repeat(ScheduleActivity.Study,24).ToArray();Until(w,()=>library.Sessions>=patron!.BaselineSessions+4,18000,"Patron's actual library obligation");Cmd(w,new(CommandKind.CampaignAction,TargetId:patron!.Id,Text:"fulfill"));Require(patron.Payments==1,"Patron demand not fulfilled.");Cmd(w,new(CommandKind.CampaignAction,TargetId:patron.Id,Text:"refuse-patron"));foreach(long id in crew){w.Interrupt(id,d);w.Colony.People[id].Schedule=Enumerable.Repeat(ScheduleActivity.Anything,24).ToArray();}Save("solar-diplomacy-and-independence",w,"Politics");Require(w.Solar.Patrons.All(p=>!p.Active),"Independence not preserved.");Console.WriteLine("PASS I03: real town-counter patron title/stock-funded aid, actual renewed library obligation, explicit refusal and trusted Sanctuary agreements; surveyed monastery and return cargo");
  }else{
   w=SaveStore.Read(Path.Combine(output,"solar-diplomacy-and-independence.lastlight"),d).World;var members=w.Society.Institutions.First(i=>i.Kind=="Library");desk=w.Find(members.HostId)!;worker=w.Colony.People.Keys.First(id=>!members.Members.Contains(id));bench=w.Entities.First(e=>e.DefinitionId=="workbench").Id;arkDesk=w.Entities.First(e=>e.DefinitionId=="study"&&e.Z==2).Id;Console.WriteLine("PASS I earned checkpoint: resumed actual verified solar stages, manufacturing, apprenticeship, cultivation and counter diplomacy for finale checks");
  }
