   var branch=Copy(w);var p=branch.Solar.Projects.Single(p=>p.Id==id);long host=id=="Sun"?branch.Slice.Ruin.EngineId:id=="Vessel"?bench:id=="Ark"?arkDesk:desk.Id;long builder=worker;branch.Colony.People[builder].Priorities[15]=1;branch.Colony.People[builder].Priorities[8]=1;branch.Colony.People[builder].Schedule=Enumerable.Repeat(ScheduleActivity.Work,24).ToArray();Cmd(branch,new(CommandKind.CampaignAction,builder,id,TargetId:host,Text:"project"));
   Until(branch,()=>p.Phase>=1,50000,id+" first transported phase");Save("solar-"+id.ToLowerInvariant()+"-in-progress",branch,"Projects");var resumed=SaveStore.Read(Path.Combine(output,"solar-"+id.ToLowerInvariant()+"-in-progress.lastlight"),d).World;Require(SaveStore.Fingerprint(branch)==SaveStore.Fingerprint(resumed),id+" partial project reload differs");Steps(branch,300);Steps(resumed,300);if(SaveStore.Fingerprint(branch)!=SaveStore.Fingerprint(resumed)){File.WriteAllText(Path.Combine(output,"solar-debug-original.json"),JsonSerializer.Serialize(branch,JsonFormat.Options));File.WriteAllText(Path.Combine(output,"solar-debug-restored.json"),JsonSerializer.Serialize(resumed,JsonFormat.Options));throw new Exception(id+" partial project continuation diverged");}
   Until(branch,()=>p.Completed,100000,id+" completed finale");Require(p.Phase==3&&p.Spent.Count>0&&branch.Solar.Finale==id&&branch.Region.History.Any(h=>h.Kind=="Finale")&&branch.Solar.Patrons.All(p=>!p.Active),id+" finale/physical ledger/independence missing");var expected=Enumerable.Range(0,3).SelectMany(phase=>branch.ProjectIngredients(id,phase)).GroupBy(k=>k.Key).ToDictionary(g=>g.Key,g=>g.Sum(k=>k.Value));Require(expected.Count==p.Spent.Count&&expected.All(k=>p.Spent.GetValueOrDefault(k.Key)==k.Value),id+" material consumption repeated or incorrect");
   if(id=="Sun")Require(branch.Solar.SunRestored&&branch.NaturalSolarLight()==100,"Regional sun does not restore light");if(id=="Vessel")Require(branch.Solar.Evacuees.Count==5&&branch.Solar.Evacuees.All(actor=>!branch.CanAct(actor)&&branch.Body(actor) is {Dead:false}),"Vessel duplicated/killed/left active evacuees");if(id=="Federation")Require(branch.Solar.Refuges.Count(r=>r.Level==3)>=3,"Federation did not fund allied refuge outcomes");if(id=="Archive")Require(branch.Solar.PreservedKnowledge.Count>=3,"Archive lost actual knowledge");Save("solar-"+id.ToLowerInvariant()+"-finale",branch,"Projects");var after=SaveStore.Read(Path.Combine(output,"solar-"+id.ToLowerInvariant()+"-finale.lastlight"),d).World;Steps(branch,900);Steps(after,900);Require(SaveStore.Fingerprint(branch)==SaveStore.Fingerprint(after),id+" completed outcome continuation diverged");if(id=="Sun"){Cmd(branch,new(CommandKind.CampaignAction,DefinitionId:"Slow Dusk",Text:"mode"));Cmd(branch,new(CommandKind.CampaignAction,DefinitionId:"Instability",Quantity:100,Text:"setting"));Require(branch.Solar.NextFlareAt==0&&branch.NaturalSolarLight()==100&&branch.SolarRules().Contains("operational"),"Restored sun promised an inactive future hazard after mode/settings changes");branch.Validate(d);}Console.WriteLine("PASS I04/I05 FINALE "+id+": real prerequisites, three hauled/consumed phases, partial reload, independent completion, typed outcome and deterministic completed save");
